fn chebweight(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    // Since input is guaranteed non-empty, n >= 1.
    if n == 1 {
        // Only one element: both start and end are the same index, weight = 0.5
        vec![0.5]
    } else {
        // For length >= 2:
        // first and last = 0.5, others = 1.0
        let mut weights = vec![1.0; n];
        weights[0] = 0.5;
        weights[n - 1] = 0.5;
        weights
    }
}